CREATE TABLE [dbo].[Sys_CodeRule] (
  [CodeRuleId] uniqueidentifier  NOT NULL,
  [TableName] nvarchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [TableCNName] nvarchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [Name] nvarchar(100) COLLATE Chinese_PRC_CI_AS  NOT NULL,
  [Code] nvarchar(100) COLLATE Chinese_PRC_CI_AS  NULL,
  [PrefixCode] nvarchar(100) COLLATE Chinese_PRC_CI_AS  NULL,
