  [ValueLen] int  NOT NULL,
  [RuleIncremental] nvarchar(1000) COLLATE Chinese_PRC_CI_AS  NULL,
  [OrderFiled] nvarchar(100) COLLATE Chinese_PRC_CI_AS  NULL,
  [ConcatenationSymbol] nvarchar(100) COLLATE Chinese_PRC_CI_AS  NULL,
  [Field] nvarchar(255) COLLATE Chinese_PRC_CI_AS  NULL,
  [CodeText1] nvarchar(200) COLLATE Chinese_PRC_CI_AS  NULL,
  [CodeText2] nvarchar(200) COLLATE Chinese_PRC_CI_AS  NULL,
  [Enable] int  NULL,
  [UserId] int  NULL,
  [TenancyId] nvarchar(100) COLLATE Chinese_PRC_CI_AS  NULL,
  [CreateID] int  NULL,
  [Creator] nvarchar(30) COLLATE Chinese_PRC_CI_AS  NULL,
  [CreateDate] datetime2(0)  NULL,
  [ModifyID] int  NULL,
  [Modifier] nvarchar(30) COLLATE Chinese_PRC_CI_AS  NULL,
  [ModifyDate] datetime2(0)  NULL,
  [DbServiceId] uniqueidentifier  NULL
)
